<template><div><div class="page-head"><div><h1>Products</h1><p class="muted">Manage the VORA catalog.</p></div><RouterLink class="btn" to="/products/new"><Plus :size="16"/> Add product</RouterLink></div><div class="filters card"><Search :size="16"/><input v-model="q" placeholder="Search products or SKU…"/><select v-model="status"><option value="">All statuses</option><option>Published</option><option>Draft</option></select></div><section class="card table-card"><div class="table-wrap"><table class="table"><thead><tr><th>Product</th><th>SKU</th><th>Category</th><th>Price</th><th>Stock</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="p in filtered" :key="p.id"><td><b>{{p.name}}</b></td><td>{{p.sku}}</td><td>{{p.category}}</td><td>{{format(p.price)}} EGP</td><td><span :class="['badge',p.stock<5?'red':'']">{{p.stock}}</span></td><td><span :class="['badge',p.status==='Published'?'green':'']">{{p.status}}</span></td><td><RouterLink :to="`/products/${p.id}/edit`">Edit</RouterLink></td></tr></tbody></table></div></section></div></template>
<script setup lang="ts">import {computed,ref} from 'vue';import {RouterLink} from 'vue-router';import {Plus,Search} from 'lucide-vue-next';import {products} from '../services/mock';const q=ref(''),status=ref('');const filtered=computed(()=>products.filter(p=>(!q.value||`${p.name} ${p.sku}`.toLowerCase().includes(q.value.toLowerCase()))&&(!status.value||p.status===status.value)));const format=(n:number)=>new Intl.NumberFormat('en-EG').format(n)</script>
<style scoped>.filters{padding:10px 12px;display:flex;align-items:center;gap:10px;margin-bottom:14px}.filters input{border:0;outline:0;flex:1}.filters select{border:1px solid #ddd;padding:8px;border-radius:7px;background:#fff}.table-card{padding:0}.table-card .table{min-width:900px}.table-card .table a{font-weight:600}.table-card .table a:hover{text-decoration:underline}</style>
